item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score cannot establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring are described for a narrow grid-puzzle comparison. The 70% describes the reported run; repeatability and conditions for fair system comparisons are insufficiently documented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated runs, stability is untested; instability is also not established."
        }
      ],
      "instrument_review": "Exact-grid scoring supports interpreting the reported puzzle performance. The documented absence of repetition leaves score consistency unknown and limits confidence in comparisons based on this single run."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations explicitly held the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing supports score consistency under the specified conditions and stated criterion. This evidence supports the narrow puzzle use; it does not establish consistency with different inputs, settings, or tasks."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly tested score variation across repeated evaluations with conditions held constant."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed variation exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "Repetition documents substantial inconsistency under the stated conditions. A single 70% score cannot adequately represent this variation; comparisons should report the repeated-run findings and acknowledge their instability."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence that repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no findings about score consistency."
        }
      ],
      "instrument_review": "Installation instructions document setup, but do not resolve missing evidence about repetition or stability. Interpretation remains limited to the reported grid-puzzle run."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A has higher observed performance on the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "The task coverage and exact-grid scoring fit the stated narrow comparison. Fixed instructions support comparability, although other resource controls and repeated-run consistency are not reported. Cross-domain conclusions exceed the evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results establish A's higher observed performance on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A stated broad intended use does not supply evidence for cross-domain intelligence."
        }
      ],
      "instrument_review": "The intended selection use exceeds the documented task coverage. Scores support a grid-puzzle comparison, but evidence connecting those scores to general intelligence across domains is missing. Other comparison controls and score consistency are also unreported."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no documented comparison of real workshop decision outcomes."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checking, and a reported difference interval of 12 to 28 percentage points support better correctness with A in the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The later preregistered randomized trial supplies direct evidence relevant to choosing assistance for correct decisions in this workshop. Blinded checking and reported uncertainty strengthen interpretation. Evidence remains limited to the studied setting and correctness outcome; time and safety benefits are unestablished."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence was distinguished from explicit conflicting evidence, and each case was assessed independently."
}
